      ('de5d14b1-0805-4088-b9cd-add1deb02808', 'a312d1dd-25c8-4a85-bca3-38bb81a7c0cd', null, 4),
      -- MASTERS · 2017 · South Central Men's Masters Regional Championships 2017 (south-central-mens-masters-regional-championships-2017) · ended 2017-06-11
      ('d0a76ee6-4e28-4132-8786-6f8a315c5377', 'fbaf82c4-a20b-48f3-b4fe-42bb2f7433a0', null, 1),
      ('d0a76ee6-4e28-4132-8786-6f8a315c5377', '8136a159-638f-4653-85b4-72f4d8e60739', null, 2)
    ) as v(event_id, team_id, old_place, new_place)
   where et.event_id = v.event_id
     and et.team_id = v.team_id
     and et.final_placement is not distinct from v.old_place;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> v_expected THEN
    RAISE EXCEPTION 'usau placements part 05: expected % rows, matched %; data drifted since generation, re-run scripts/derive-usau-placements.ts', v_expected, v_updated;
  END IF;
  RAISE NOTICE 'usau placements part 05: updated % rows', v_updated;
END
